script:
(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const arm = () => {
        document.documentElement.classList.add("fa-js");
        document.querySelectorAll("video").forEach((video) => {
            video.muted = true;
            const playing = video.play();
            if (playing) playing.catch(() => {});
        });
        const io = new IntersectionObserver((entries) => {
            for (const entry of entries) {
                if (!entry.isIntersecting) continue;
                entry.target.classList.add("fa-in");
                io.unobserve(entry.target);
            }
        }, { threshold: 0.12, rootMargin: "0px 0px -8% 0px" });
        document.querySelectorAll(".fa-rise").forEach((el) => io.observe(el));

        const scenes = Array.from(document.querySelectorAll("[data-scene]"));
        const gauges = Array.from(document.querySelectorAll("[data-depth]"));
        const pageDepth = document.querySelector("[data-max-depth]");
        const clamp01 = (x) => Math.min(1, Math.max(0, x));
        let ticking = false;
        const update = () => {
            ticking = false;
            let depth = 0;
            for (const scene of scenes) {
                const rect = scene.getBoundingClientRect();
                const track = rect.height - window.innerHeight;
                const p = track > 0 ? clamp01(-rect.top / track) : 0;
                scene.style.setProperty("--p", p.toFixed(4));
                depth = Math.max(depth,
                    p * parseFloat(scene.getAttribute("data-scene") || "0"));
                scene.querySelectorAll("[data-at]").forEach((wp) => {
                    const from = parseFloat(wp.getAttribute("data-at"));
                    const until = parseFloat(wp.getAttribute("data-until") || "2");
                    wp.classList.toggle("fa-on", p >= from && p < until);
                    wp.classList.toggle("fa-past", p >= until);
                });
            }
            if (!scenes.length && pageDepth) {
                const doc = document.documentElement;
                const p = clamp01(doc.scrollTop /
                    Math.max(1, doc.scrollHeight - window.innerHeight));
                depth = p * parseFloat(pageDepth.getAttribute("data-max-depth"));
            }
            const reading = depth.toFixed(1) + " m";
            for (const gauge of gauges) {
                if (gauge.textContent !== reading) gauge.textContent = reading;
            }
        };
        const onScroll = () => {
            if (ticking) return;
            ticking = true;
            requestAnimationFrame(update);
        };
        window.addEventListener("scroll", onScroll, { passive: true });
        window.addEventListener("resize", onScroll, { passive: true });
        update();
    };
    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", arm);
    } else {
        arm();
    }
})();
